SELECT COUNT(*)
FROM user_checkins
WHERE user_id = #{userId}
  AND place_id = #{placeId}
  AND is_removed = FALSE

SELECT COUNT(*)
FROM user_checkins
WHERE user_id = #{userId}
  AND location_key = #{locationKey}
  AND is_removed = FALSE

SELECT id, checkin_id, url, source, position, captured_at, latitude, longitude, accuracy_meters, created_at FROM user_checkin_photos WHERE checkin_id IN
#{checkinId}
ORDER BY checkin_id, position

SELECT checkin_id FROM user_checkin_likes
WHERE user_id = #{userId} AND checkin_id IN
#{id}
